begin;
select plan(44);
insert into auth.users(id,email) values ('a6280000-0000-0000-0000-000000000001','settle@example.com');
insert into public.profiles(id,auth_user_id,full_name,email,status) values ('b6280000-0000-0000-0000-000000000001','a6280000-0000-0000-0000-000000000001','Settlement','settle@example.com','active');
insert into public.user_roles(user_id,role_id) select 'b6280000-0000-0000-0000-000000000001',id from public.roles where name='admin';
insert into auth.users(id,email) values ('a6280000-0000-0000-0000-000000000002','settle-denied@example.com');
insert into public.profiles(id,auth_user_id,full_name,email,status) values ('b6280000-0000-0000-0000-000000000002','a6280000-0000-0000-0000-000000000002','Denied','settle-denied@example.com','active');
insert into auth.users(id,email) values ('a6280000-0000-0000-0000-000000000003','collector@example.com');
insert into public.profiles(id,auth_user_id,full_name,email,status) values ('b6280000-0000-0000-0000-000000000003','a6280000-0000-0000-0000-000000000003','Collector','collector@example.com','active');
select set_config('request.jwt.claims','{"sub":"a6280000-0000-0000-0000-000000000001","role":"authenticated"}',true);
create temp table ids(k text primary key,id uuid); grant select,insert on ids to authenticated;
create function pg_temp.id(k text) returns uuid language sql stable as $$select id from ids where k=$1$$; grant execute on function pg_temp.id(text) to authenticated;
with x as (insert into public.campaigns(name,simple_bond_value,installment_count,installment_value,barcode_mode) values('S',100,2,50,'base_number') returning id) insert into ids select 'c',id from x;
with x as (insert into public.collectors(display_name,user_profile_id) values('Ana','b6280000-0000-0000-0000-000000000003') returning id) insert into ids select 'collector',id from x;
with x as (insert into public.buyers(type,first_name) values('individual','Eva') returning id) insert into ids select 'buyer',id from x;
with x as (insert into public.bonds(campaign_id,kind,origin,commercial_unit_count,total_value,commercial_status) values(pg_temp.id('c'),'simple','printed',1,100,'available') returning id) insert into ids select 'bond',id from x;
with x as (insert into public.sales(campaign_id,bond_id,buyer_id,collector_id,payment_mode,total_amount,created_by) values(pg_temp.id('c'),pg_temp.id('bond'),pg_temp.id('buyer'),pg_temp.id('collector'),'installments',100,'b6280000-0000-0000-0000-000000000001') returning id) insert into ids select 'sale',id from x;
with x as (insert into public.payment_plans(sale_id,installment_count,total_amount) values(pg_temp.id('sale'),2,100) returning id) insert into ids select 'plan',id from x;
with x as (insert into public.installments(payment_plan_id,installment_number,due_date,amount) select pg_temp.id('plan'),n,current_date+1,50 from generate_series(1,2)n returning id,installment_number) insert into ids select 'i'||installment_number,id from x;
set local role authenticated;
with x as (select public.settlement_open(pg_temp.id('c'),pg_temp.id('collector'),' note ','r1') id) insert into ids select 'set',id from x;
select is((select settlement_number from public.settlements where id=pg_temp.id('set')),1,'opens next numbered settlement');
select throws_ok($$select public.settlement_add_payment(pg_temp.id('set'),pg_temp.id('sale'),10,'cash',jsonb_build_array(jsonb_build_object('installment_id',pg_temp.id('i1'),'amount_applied',9)))$$,'22023','payment applications must equal the payment amount','applications must sum to the payment');
select lives_ok($$select public.settlement_add_payment(pg_temp.id('set'),pg_temp.id('sale'),100,'cash',jsonb_build_array(jsonb_build_object('installment_id',pg_temp.id('i1'),'amount_applied',50),jsonb_build_object('installment_id',pg_temp.id('i2'),'amount_applied',50)))$$,'adds multi-installment cash payment');
select is((select total_cash from public.settlement_totals(pg_temp.id('set'))),100::numeric,'preliminary cash total');
select is((select total_amount from public.settlement_totals(pg_temp.id('set'))),100::numeric,'preliminary total');
select lives_ok($$select public.settlement_close(pg_temp.id('set'))$$,'closes atomically');
select is((select status from public.payments where settlement_id=pg_temp.id('set')),'confirmed','close confirms payment');
select is((select count(*)::int from public.installments where status='paid_advance'),2,'close advances covered installments');
select is((select status from public.settlements where id=pg_temp.id('set')),'closed','close locks settlement');
select throws_ok($$select public.settlement_close(pg_temp.id('set'))$$,'55000','settlement must be open','closed settlement cannot reopen through RPC');
select throws_ok($$select public.settlement_add_payment(pg_temp.id('set'),pg_temp.id('sale'),1,'transfer',jsonb_build_array(jsonb_build_object('installment_id',pg_temp.id('i1'),'amount_applied',1)))$$,'55000','settlement must be open','closed settlement cannot be edited');
reset role;
select is((select count(*)::int from public.audit_log where action in ('settlement.open','payment.add','settlement.close')),3,'one audit row per settlement operation');
select ok(has_function_privilege('authenticated','public.settlement_close(uuid,text)','execute') and not has_function_privilege('anon','public.settlement_close(uuid,text)','execute'),'RPC privileges are explicit');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a6280000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.settlement_totals(pg_temp.id('set'))$$,'42501','permission denied: settlement.view is required','role-less user cannot bypass settlement RLS via totals RPC');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a6280000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select is((select collector_credit_balance from public.settlement_totals(pg_temp.id('set'))),0::numeric,'credit balance is zero until collector ledger entries exist');
reset role;
-- A second sale provides open installments for annulment, mixed totals, and rollback cases.
with x as (insert into public.bonds(campaign_id,kind,origin,commercial_unit_count,total_value,commercial_status) values(pg_temp.id('c'),'simple','printed',1,100,'available') returning id) insert into ids select 'bond2',id from x;
with x as (insert into public.sales(campaign_id,bond_id,buyer_id,collector_id,payment_mode,total_amount,created_by) values(pg_temp.id('c'),pg_temp.id('bond2'),pg_temp.id('buyer'),pg_temp.id('collector'),'installments',100,'b6280000-0000-0000-0000-000000000001') returning id) insert into ids select 'sale2',id from x;
with x as (insert into public.payment_plans(sale_id,installment_count,total_amount) values(pg_temp.id('sale2'),2,100) returning id) insert into ids select 'plan2',id from x;
with x as (insert into public.installments(payment_plan_id,installment_number,due_date,amount) select pg_temp.id('plan2'),n,current_date+1,50 from generate_series(1,2)n returning id,installment_number) insert into ids select 'j'||installment_number,id from x;
set local role authenticated;
with x as (select public.settlement_open(pg_temp.id('c'),pg_temp.id('collector'),null) id) insert into ids select 'remove_set',id from x;
with x as (select public.settlement_add_payment(pg_temp.id('remove_set'),pg_temp.id('sale2'),10,'cash',jsonb_build_array(jsonb_build_object('installment_id',pg_temp.id('j1'),'amount_applied',10))) id) insert into ids select 'remove_payment',id from x;
select lives_ok($$select public.settlement_remove_payment(pg_temp.id('remove_payment'),' duplicate receipt ')$$,'removes a pending payment');
select is((select status from public.payments where id=pg_temp.id('remove_payment')),'annulled','removed payment is annulled');
select is((select total_amount from public.settlement_totals(pg_temp.id('remove_set'))),0::numeric,'annulled payment is excluded from totals');
reset role;
select is((select reason from public.audit_log where action='payment.annul' and entity_id=pg_temp.id('remove_payment')::text),'duplicate receipt','annulment audit preserves reason');
set local role authenticated;
select throws_ok($$select public.settlement_remove_payment(pg_temp.id('remove_payment'),repeat('x',1001))$$,'22023','a trimmed annulment reason of at most 1000 characters is required','1001-character reason is rejected');
select lives_ok($$select public.settlement_add_payment(pg_temp.id('remove_set'),pg_temp.id('sale2'),40,'transfer',jsonb_build_array(jsonb_build_object('installment_id',pg_temp.id('j1'),'amount_applied',40)))$$,'adds transfer payment');
select is((select total_transfer from public.settlement_totals(pg_temp.id('remove_set'))),40::numeric,'transfer total is calculated');
select lives_ok($$select public.settlement_add_payment(pg_temp.id('remove_set'),pg_temp.id('sale2'),10,'cash',jsonb_build_array(jsonb_build_object('installment_id',pg_temp.id('j1'),'amount_applied',10)))$$,'adds cash payment');
select is((select total_amount from public.settlement_totals(pg_temp.id('remove_set'))),50::numeric,'mixed cash and transfer total is calculated');
select lives_ok($$select public.settlement_close(pg_temp.id('remove_set'))$$,'closes settlement');
select throws_ok($$select public.settlement_remove_payment(pg_temp.id('remove_payment'),'too late')$$,'55000','only a pending payment in an open settlement can be removed','closed settlement rejects removal');
-- Every RPC verifies its own permission.
select set_config('request.jwt.claims','{"sub":"a6280000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.settlement_open(pg_temp.id('c'),pg_temp.id('collector'),null)$$,'42501','permission denied: settlement.create is required','denies open');
select throws_ok($$select public.settlement_add_payment(pg_temp.id('set'),pg_temp.id('sale'),1,'cash',jsonb_build_array(jsonb_build_object('installment_id',pg_temp.id('i1'),'amount_applied',1)))$$,'42501','permission denied: payment.create is required','denies add payment');
select throws_ok($$select public.settlement_remove_payment(pg_temp.id('remove_payment'),'nope')$$,'42501','permission denied: settlement.update_open is required','denies remove payment');
select throws_ok($$select public.settlement_close(pg_temp.id('set'))$$,'42501','permission denied: settlement.close is required','denies close');
select throws_ok($$select public.settlement_totals(pg_temp.id('set'))$$,'42501','permission denied: settlement.view is required','denies totals');
select set_config('request.jwt.claims','{"sub":"a6280000-0000-0000-0000-000000000001","role":"authenticated"}',true);
with x as (select public.settlement_open(pg_temp.id('c'),pg_temp.id('collector'),null) id) insert into ids select 'rollback_set',id from x;
with x as (select public.settlement_add_payment(pg_temp.id('rollback_set'),pg_temp.id('sale2'),50,'cash',jsonb_build_array(jsonb_build_object('installment_id',pg_temp.id('j2'),'amount_applied',50))) id) insert into ids select 'rollback_payment',id from x;
reset role;
create function pg_temp.fail_settlement_close() returns trigger language plpgsql as $$begin raise exception 'test close failure'; end$$;
create trigger test_fail_settlement_close before update on public.settlements for each row execute function pg_temp.fail_settlement_close();
set local role authenticated;
select throws_ok($$select public.settlement_close(pg_temp.id('rollback_set'))$$,'P0001','test close failure','close failure is surfaced');
reset role;
drop trigger test_fail_settlement_close on public.settlements;
select is((select status from public.payments where id=pg_temp.id('rollback_payment')),'pending_in_settlement','failed close leaves payment pending');
select is((select status from public.installments where id=pg_temp.id('j2')),'pending','failed close leaves installment unchanged');
select is((select status from public.settlements where id=pg_temp.id('rollback_set')),'open','failed close leaves settlement open');
with x as (insert into public.collectors(display_name) values('Bea') returning id) insert into ids select 'collector2',id from x;
with x as (insert into public.bonds(campaign_id,kind,origin,commercial_unit_count,total_value,commercial_status) values(pg_temp.id('c'),'simple','printed',1,100,'available') returning id) insert into ids select 'bond3',id from x;
with x as (insert into public.sales(campaign_id,bond_id,buyer_id,collector_id,payment_mode,total_amount,created_by) values(pg_temp.id('c'),pg_temp.id('bond3'),pg_temp.id('buyer'),pg_temp.id('collector2'),'installments',100,'b6280000-0000-0000-0000-000000000001') returning id) insert into ids select 'sale_other_collector',id from x;
set local role authenticated;
select throws_ok($$select public.settlement_add_payment(pg_temp.id('rollback_set'),pg_temp.id('sale_other_collector'),1,'cash','[]')$$,'22023','sale must be active and belong to the settlement collector and campaign','rejects another collector sale');
with x as (select public.settlement_open(pg_temp.id('c'),pg_temp.id('collector2'),null) id) insert into ids select 'other_set',id from x;
select throws_ok($$select public.settlement_add_payment(pg_temp.id('other_set'),pg_temp.id('sale2'),1,'cash','[]')$$,'22023','sale must be active and belong to the settlement collector and campaign','rejects another collector settlement');
select set_config('request.jwt.claims','{"sub":"a6280000-0000-0000-0000-000000000003","role":"authenticated"}',true);
select lives_ok($$select public.settlement_totals(pg_temp.id('set'))$$,'collector login can read its own settlement totals');
select throws_ok($$select public.settlement_totals(pg_temp.id('other_set'))$$,'42501','permission denied: settlement.view is required','collector login cannot read another collector totals');
reset role;
-- Commission selection covers percentage, fixed prorating, collector override, and middle/last rules.
with x as (insert into public.campaigns(name,simple_bond_value,installment_count,installment_value,barcode_mode) values('Commission',150,3,50,'base_number') returning id) insert into ids select 'commission_campaign',id from x;
insert into public.commission_rules(campaign_id,rule_type,percentage,valid_from,status)
values (pg_temp.id('commission_campaign'),'installment_middle',10,current_date,'active');
insert into public.commission_rules(campaign_id,rule_type,fixed_amount,valid_from,status)
values (pg_temp.id('commission_campaign'),'installment_last',10,current_date,'active');
insert into public.commission_rules(campaign_id,rule_type,fixed_amount,applies_to_collector_id,valid_from,status)
values (pg_temp.id('commission_campaign'),'installment_last',15,pg_temp.id('collector'),current_date,'active');
select is(public.settlement_application_commission(pg_temp.id('commission_campaign'),pg_temp.id('collector2'),current_date,'installments',2,3,50,50),5::numeric,'percentage commission applies to middle installment');
select is(public.settlement_application_commission(pg_temp.id('commission_campaign'),pg_temp.id('collector2'),current_date,'installments',3,3,25,50),5::numeric,'fixed commission is prorated for partial installment');
select is(public.settlement_application_commission(pg_temp.id('commission_campaign'),pg_temp.id('collector'),current_date,'installments',3,3,50,50),15::numeric,'collector-specific rule overrides general rule');
select ok(public.settlement_application_commission(pg_temp.id('commission_campaign'),pg_temp.id('collector2'),current_date,'installments',2,3,50,50) = 5
  and public.settlement_application_commission(pg_temp.id('commission_campaign'),pg_temp.id('collector2'),current_date,'installments',3,3,50,50) = 10,'middle and last installments select different rules');
select is((select financial_status_snapshot from public.bonds where id=pg_temp.id('bond')),'fully_paid','closing updates bond financial status snapshot');
select * from finish(); rollback;
